True def transform(grid):
    out = [row[:] for row in grid]
    n, m = len(grid), len(grid[0])
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 3:
                mirrors = ((r, m - 1 - c), (n - 1 - r, c), (n - 1 - r, m - 1 - c))
                values = [grid[rr][cc] for rr, cc in mirrors if grid[rr][cc] != 3]
                if values:
                    out[r][c] = values[0]
    return out
